package com.wansheng.visitor.auth;
import java.sql.*;import java.time.Instant;import java.util.*;import org.springframework.dao.DuplicateKeyException;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.userdetails.*;import org.springframework.stereotype.Repository;import org.springframework.web.server.ResponseStatusException;
@Repository class AccountRepository{private final JdbcTemplate jdbc;AccountRepository(JdbcTemplate j){jdbc=j;}record Account(long id,String username,String displayName,String role,boolean enabled,Instant createdAt){}List<Account>list(){return jdbc.query("SELECT id,username,display_name,role_code,enabled,created_at FROM user_account ORDER BY id",this::map);}Optional<Account>find(String u){return jdbc.query("SELECT id,username,display_name,role_code,enabled,created_at FROM user_account WHERE username=?",this::map,u).stream().findFirst();}UserDetails loadUser(String u){return jdbc.query("SELECT username,password_hash,role_code,enabled FROM user_account WHERE username=?",(r,n)->User.withUsername(r.getString(1)).password(r.getString(2)).roles(r.getString(3)).disabled(!r.getBoolean(4)).build(),u).stream().findFirst().orElseThrow(()->new UsernameNotFoundException(u));}void create(String u,String n,String h,String role){try{jdbc.update("INSERT INTO user_account(username,display_name,password_hash,role_code,enabled,created_at,updated_at) VALUES(?,?,?,?,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",u,n,h,role);}catch(DuplicateKeyException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"用户名已存在");}}int update(String u,String n,String role,boolean enabled){return jdbc.update("UPDATE user_account SET display_name=?,role_code=?,enabled=?,updated_at=CURRENT_TIMESTAMP WHERE username=?",n,role,enabled,u);}int password(String u,String h){return jdbc.update("UPDATE user_account SET password_hash=?,updated_at=CURRENT_TIMESTAMP WHERE username=?",h,u);}int delete(String u){return jdbc.update("DELETE FROM user_account WHERE username=?",u);}int enabledSystemAdmins(){return jdbc.queryForObject("SELECT COUNT(*) FROM user_account WHERE role_code='SYSTEM_ADMIN' AND enabled=TRUE",Integer.class);}private Account map(ResultSet r,int n)throws SQLException{return new Account(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getBoolean(5),r.getTimestamp(6).toInstant());}}
